// Total Time Complexity: O(n * log n)

// In-place remove duplicates from sorted array
function removeDuplicates(nums) {
    if (nums.length === 0) return 0;
    let slow = 0;
    for (let fast = 1; fast < nums.length; fast++) {
        if (nums[fast] !== nums[slow]) {
            slow++;
            nums[slow] = nums[fast]; // Overwrite next distinct position
        }
    }
    return slow + 1;
}

// Longest Substring Without Repeating Characters
function lengthOfLongestSubstring(s) {
    let seen = new Map();
    let maxLen = 0, left = 0;
    for (let right = 0; right < s.length; right++) {
        if (seen.has(s[right])) {
            left = Math.max(left, seen.get(s[right]) + 1);
        }
        seen.set(s[right], right);
        maxLen = Math.max(maxLen, right - left + 1);
    }
    return maxLen;
}

// Canonical Binary Search Implementation
function binarySearch(arr, target) {
    let low = 0;
    let high = arr.length - 1;

    while (low <= high) {
        // Avoid (low + high) / 2 overflow
        let mid = low + Math.floor((high - low) / 2);

        if (arr[mid] === target) {
            return mid; // Target found at index mid
        }

        if (arr[mid] < target) {
            // Target is in the right subarray -> discard mid and left
            low = mid + 1;
        } else {
            // Target is in the left subarray -> discard mid and right
            high = mid - 1;
        }
    }

    return -1; // Target not found
}

// Lomuto Partition Scheme
function partition(arr, low, high) {
    let pivot = arr[high];
    let i = low - 1;
    for (let j = low; j < high; j++) {
        if (arr[j] <= pivot) {
            i++;
            [arr[i], arr[j]] = [arr[j], arr[i]];
        }
    }
    [arr[i + 1], arr[high]] = [arr[high], arr[i + 1]];
    return i + 1;
}

// Reverse Singly Linked List In-Place
function reverseList(head) {
    let prev = null;
    let curr = head;
    while (curr !== null) {
        let nextTemp = curr.next; // Save next node
        curr.next = prev;         // Reverse pointer
        prev = curr;              // Advance prev
        curr = nextTemp;          // Advance curr
    }
    return prev; // New head
}

// Next Greater Element using Monotonic Decreasing Stack
function nextGreaterElements(nums) {
    let res = new Array(nums.length).fill(-1);
    let stack = []; // store indices
    for (let i = 0; i < nums.length; i++) {
        while (stack.length && nums[stack[stack.length - 1]] < nums[i]) {
            let idx = stack.pop();
            res[idx] = nums[i];
        }
        stack.push(i);
    }
    return res;
}

// Binary Heap Parent-Child Mapping
// arr = [10, 15, 20, 17, 25]
// Parent of index 3 (val 17) is index Math.floor((3-1)/2) = 1 (val 15)

// Validate Binary Search Tree using Recursion Range Invariant
function isValidBST(root, min = -Infinity, max = Infinity) {
    if (!root) return true;
    if (root.val <= min || root.val >= max) return false;
    // Left subtree must be < root.val, Right subtree must be > root.val
    return isValidBST(root.left, min, root.val) && isValidBST(root.right, root.val, max);
}

